mapper.select:
SELECT handlers.handler_id AS handlerId, handlers.handler_name AS handlerName, dates.stat_date AS statDate, COUNT(t.id) AS count FROM ( SELECT u.id AS handler_id, COALESCE(NULLIF(u.real_name, ''), u.username) AS handler_name FROM users u WHERE u.role = 1 AND u.status = 1 AND EXISTS ( SELECT 1 FROM handler_profiles hp WHERE hp.user_id = u.id ) ) handlers CROSS JOIN (
SELECT #{date,jdbcType=DATE} AS stat_date
) dates LEFT JOIN tickets t ON t.handler_id = handlers.handler_id AND t.created_at < DATE_ADD(dates.stat_date, INTERVAL 1 DAY) AND ( t.closed_at IS NULL OR t.closed_at >= DATE_ADD(dates.stat_date, INTERVAL 1 DAY) ) GROUP BY handlers.handler_id, handlers.handler_name, dates.stat_date ORDER BY handlers.handler_id, dates.stat_date
